// Error Trigger payload: { execution: { id, url, lastNodeExecuted, error, mode }, workflow: { id, name } }
const e = $json.execution ?? {};
return [{ json: {
  execution_id: String(e.id ?? ''),
  execution_url: e.url ?? '',
  failed_node: e.lastNodeExecuted ?? e.error?.node?.name ?? 'unknown',
  error_message: String(e.error?.message ?? 'unknown error').slice(0, 500),
  workflow_name: $json.workflow?.name ?? ''
}}];

