// `mark failed` returns { id } when it marked a row. With no matching row (the run died before
// `record received`, e.g. an invalid email) Postgres outputs { success: true } instead - check.
const err = $('read error').first().json;
const row = $input.first()?.json ?? {};
const enquiryId = row.id ?? '';

// No customer data in the alert (it leaves our systems via Telegram) - just the id to look up.
const lines = [
  '🚨 Enquiry Desk — run failed',
  'Node: ' + err.failed_node,
  'Error: ' + err.error_message,
  enquiryId
    ? 'Enquiry: ' + enquiryId + '\nStatus → failed (dead_letter). Replay: python3 test/replay.py'
    : 'No enquiry row — it failed before intake (nothing to replay).',
  err.execution_url ? 'Execution: ' + err.execution_url : 'Execution id: ' + err.execution_id
];
return [{ json: { ...err, enquiry_id: enquiryId, text: lines.join('\n') } }];
